def is_woodall(x): 
    if x == 0 or x == 1:
        return True
    if x % 2 == 0:
        return False
    while True:
        x = x + 1
        p = 0
        while x % 2 == 0:
            x //= 2
            p += 1
        if p == x:
            return True
        if p < x:
            return False
```

