def bell_number(n):
    if n <= 0:
        return 1
    B = [1] * (n + 1)
    for i in range(1, n + 1):
        for j in range(i, 0, -1):
            B[j] += B[j - 1]
    return B[n]
```

```python
def bell_number(n):
    if n == 0:
        return 1
    dp = [0] * (n + 1)
    dp[0] = 1
    for i in range(1, n + 1):
        new_dp = [0] * (n + 1)
        for j in range(i + 1):
            new_dp[j] = dp[j - 1] + (dp[j] if j < len(dp) else 0)
        dp = new_dp
    return dp[n]
```

```python
def bell_number(n):
    bell = [[0] * (n + 1) for _ in range(n + 1)]
    bell[0][0] = 1
    for i in range(1, n + 1):
        bell[i][0] = bell[i - 1][i - 1]
        for j in range(1, i + 1):
            bell[i][j] = bell[i - 1][j - 1] + bell[i][j - 1]
    return bell[n][0]
```

