def is_undulating(n):
    s = str(n)
    if len(s) < 3:
        return False
    # All digits must be the same -> not undulating
    if len(set(s)) == 1:
        return False
    for i in range(2, len(s)):
        if s[i] == s[i-2]:
            continue
        else:
            return False
    return False
```

