def find_solution(a, b, n):
    if a == 0 and b == 0:
        return None if n != 0 else (0, 0)
    if a == 0:
        return None if n % b != 0 else (0, n // b)
    if b == 0:
        return None if n % a != 0 else (n // a, 0)
    g, x0, y0 = extended_gcd(a, b)
    if n % g != 0:
        return None
    x = x0 * (n // g)
    y = y0 * (n // g)
    k = (a * x0 + b * y0 - n) // g
    return (x - k * b, y + k * a)

def extended_gcd(a, b):
    if b == 0:
        return a, 1, 0
    g, x1, y1 = extended_gcd(b, a % b)
    return g, y1, x1 - (a // b) * y1
```

