    if n % 2 == 1:
        mid = n // 2
        if arr[mid] != x:
            return False
        left_count = count_less(arr, mid, x)
        right_count = count_less(arr, mid + 1, x) - count_less(arr, mid, x)
        return left_count + right_count > n // 2
    else:
        mid = n // 2
        if arr[mid] != x or arr[mid - 1] != x:
            return False
        left_count = count_less(arr, mid - 1, x)
        right_count = count_less(arr, mid, x) - count_less(arr, mid - 1, x)
        return left_count + right_count > n // 2

