def is_majority(arr, n, x):
    # Find first occurrence of x
    left, right = 0, n - 1
    first = -1
    while left <= right:
        mid = (left + right) // 2
        if arr[mid] == x:
            if mid == 0 or arr[mid - 1] != x:
                first = mid
                break
            right = mid - 1
        elif arr[mid] < x:
            left = mid + 1
        else:
            right = mid - 1

    if first == -1:
        return False

    # Check if x appears more than n/2 times by looking at the position after the majority window
    last_expected_index = first + (n // 2)
    if last_expected_index < n and arr[last_expected_index] == x:
        return True
    return False
