def get_total_number_of_sequences(m, n):
    T = [[0] * (n + 1) for _ in range(m + 1)]
    for i in range(m + 1):
        for j in range(n + 1):
            if j == 0:
                T[i][j] = 0
            elif j == 1:
                T[i][j] = i
            else:
                # For a sequence of length j ending with value i,
                # the previous element must be in [ceil(i/2), i-1].
                low = (i + 1) // 2
                if low > i - 1:
                    T[i][j] = T[i-1][j-1] if i >= 1 else 0
                else:
                    T[i][j] = sum(T[k][j-1] for k in range(low, i))
    return T[m][n]
