def get_total_number_of_sequences(m, n):
    if n == 0:
        return 1
    if m < 1:
        return 0

    # dp[i][j] = number of valid sequences of length j ending with value i
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    # Base case: sequences of length 1
    for i in range(1, m + 1):
        dp[i][1] = 1

    for length in range(2, n + 1):
        for current in range(1, m + 1):
            # previous element must be in [ceil(current/2), current-1]
            lower = (current + 1) // 2  # smallest x such that 2*x <= current => x <= current//2, but we need x >= current/2 -> x in [ceil(current/2), current-1]
            # Actually: prev >= current/2  => prev in [ceil(current/2), current-1]
            start = (current + 1) // 2
            if start < current:
                for prev in range(start, current):
                    if prev <= m:
                        dp[current][length] += dp[prev][length - 1]

    return sum(dp[i][n] for i in range(1, m + 1))
