def get_total_number_of_sequences(m, n):
    from functools import lru_cache

    @lru_cache(maxsize=None)
    def dp(x, k):
        # Number of sequences of length k starting with value >= x,
        # where each next element is at least twice the previous,
        # and all elements are <= m.
        if k == 1:
            return m - x + 1 if x <= m else 0
        total = 0
        for nxt in range(max(2 * x, x), m + 1):
            total += dp(nxt, k - 1)
        return total

    return dp(1, n)
```

