def get_total_number_of_sequences(m, n):
    from functools import lru_cache

    @lru_cache(None)
    def dp(limit, length):
        if length == 1:
            return limit
        if limit == 0:
            return 0
        total = 0
        for start in range(2 * limit, limit + 1):
            total += dp(start, length - 1)
        return total

    return dp(1, n)
