def count_no_of_ways(n, k):
    if n == 0:
        return 0
    if n == 1:
        return k
    if k == 0:
        return 0
    same = k      # ways where current post is same as previous
    diff = k * (k - 1)  # ways where current post is different from previous
    for _ in range(2, n):
        new_same = diff
        new_diff = (same + diff) * (k - 1)
        same, diff = new_same, new_diff
    return same + diff
```

