def get_max_sum(n):
    if n < 0:
        return 0
    if n == 0:
        return 0
    if n == 1:
        return 1
    memo = [0] * (n + 1)
    memo[1] = 1
    for i in range(2, n + 1):
        s = i
        if i // 2 >= 0:
            s += memo[i // 2]
        if i // 3 >= 0:
            s += memo[i // 3]
        if i // 4 >= 0:
            s += memo[i // 4]
        if i // 5 >= 0:
            s += memo[i // 5]
        memo[i] = max(i, s)
    return memo[n]
