def find_adverb_position(text):
    n = len(text)
    for i in range(n):
        if i + 3 <= n and text[i:i+3] == 'ly' and i > 0 and text[i-1].isalpha():
            j = i - 1
            while j > 0 and text[j-1].isalpha():
                j -= 1
            return (j, i + 2, text[j:i+2])
    return (-1, -1, '')
```

