def cal_sum(n):
    if n < 0:
        return 0
    p = [0] * (n + 1)
    p[0] = 3
    if n >= 1:
        p[1] = 0
    if n >= 2:
        p[2] = 2
    for i in range(3, n + 1):
        p[i] = p[i-3] + p[i-2]
    return sum(p)
