import math

def sumofFactors(n: int) -> int:
    if n <= 0:
        return 0
    if n % 2 != 0:
        return 0

    res = 1
    d = 2
    while d * d <= n:
        if n % d == 0:
            power_sum = 0
            term = 1
            while n % d == 0:
                n //= d
                term *= d
                power_sum += term
            res *= power_sum
        d += 1
    if n > 1:
        res *= (1 + n)
    return res
```

