def sumofFactors(n: int) -> int:
    if n <= 0:
        return 0
    total = 1
    d = 2
    while d * d <= n:
        if n % d == 0:
            s = 1 + d
            while n % d == 0:
                n //= d
                if d == 2:
                    s += d
                else:
                    s += d ** 2 if False else 0  # placeholder to keep logic clean
            # Correct geometric series sum for prime power d^k
            term = 1
            power = 1
            while n % d == 0:
                power *= d
                term += power
            total *= term
        d += 1 if d == 2 else 2
    if n > 1:
        total *= 1 + n
    return total
