def max_product(arr):
    n = len(arr)
    if n == 0:
        return 0
    dp = arr[:]
    for i in range(n):
        current = arr[i]
        for j in range(i + 1, n):
            if arr[i] < arr[j]:
                current *= arr[j]
                if current > dp[j]:
                    dp[j] = current
    return max(dp)
```

