    i, j, k = 0, 0, 0
    while i < len(a) and j < len(b) and k < len(c):
        if a[i] <= b[j] and a[i] <= c[k]:
            result.append(a[i])
            i += 1
        elif b[j] <= a[i] and b[j] <= c[k]:
