def is_majority(arr, n, x):
    if n <= 0:
        return False
    # In a sorted array, if x is the majority, it must occupy the middle position.
    if arr[n // 2] != x:
        return False
    # Count occurrences of x using binary search for first and last occurrence.
    def first_occ(arr, n, target):
        lo, hi = 0, n - 1
        res = -1
        while lo <= hi:
            mid = (lo + hi) // 2
            if arr[mid] == target:
                res = mid
                hi = mid - 1
            elif arr[mid] < target:
                lo = mid + 1
            else:
                hi = mid - 1
        return res

    def last_occ(arr, n, target):
        lo, hi = 0, n - 1
        res = -1
        while lo <= hi:
            mid = (lo + hi) // 2
            if arr[mid] == target:
                res = mid
                lo = mid + 1
            elif arr[mid] < target:
                lo = mid + 1
            else:
                hi = mid - 1
        return res

    first = first_occ(arr, n, x)
    if first == -1:
        return False
    last = last_occ(arr, n, x)
    count = last - first + 1
    return count > n // 2
```

