```python
def next_smallest_palindrome(n: int) -> int:
    # Special case for single-digit numbers (though not in tests, good to handle)
    if n < 10:
        return n + 1

    # Try incrementing the middle digit(s) and mirroring
    s = str(n)
    length = len(s)
    half = length // 2

    # Try to form a palindrome by taking the left half and mirroring it
    left_half = s[:half]
    for i in range(half, -1, -1):
        # Try increasing the digit at position i
        digit = str(int(left_half[i]) + 1)
        if len(digit) == 1:
            # Construct candidate by mirroring the modified left half
            if length % 2 == 1:
                # Odd length: skip the middle digit in mirroring
                right = left_half[:i][::-1] + digit + left_half[:i][::-1]
            else:
                # Even length: mirror fully
                right = digit + left_half[:i][::-1]
            candidate = left_half[:i] + digit + right
            if int(candidate) > n:
                return int(candidate)

    # If no single-digit change works, add 1 to the left half and re-mirror
    left_half_inc = str(int(left_half) + 1)
    if len(left_half_inc) == len(left_half):
        if length % 2 == 1:
            right = left_half_inc[:-1][::-1]
        else:
            right = left_half_inc[:-1][::-1]
        candidate = left_half_inc + right
        return int(candidate)
    else:
        # Carry propagated, e.g., 99 -> 101
        return int("1" + "0" * (length - 1) + "1")
```

