def get_max_sum(n: int) -> int:
    memo = {0: 0, 1: 1}
    def dp(x: int) -> int:
        if x in memo:
            return memo[x]
        take_split = dp(x // 2) + dp(x // 3) + dp(x // 4) + dp(x // 5)
        take_self = x
        memo[x] = max(take_split, take_self)
        return memo[x]
    return dp(n)
```

