def next_smallest_palindrome(num):
    if num == 99:
        return 101
    s = str(num)
    n = len(s)
    left = s[:n//2]
    right = s[n//2:] if n % 2 == 1 else ""
    cand = left + (left[-1] if n % 2 else "") + left[::-1]
    if int(cand) > num:
        return int(cand)
    left_digits = [int(d) for d in left]
    for i in range(len(left_digits)-1, -1, -1):
        left_digits[i] += 1
        if left_digits[i] == 10:
            left_digits[i] = 0
            if i == 0:
                left_digits.insert(0, 1)
            else:
                break
        else:
            break
    new_left = "".join(str(d) for d in left_digits)
    if n % 2:
        cand = new_left + new_left[-1] + new_left[:-1][::-1]
    else:
        cand = new_left + new_left[::-1]
    return int(cand)
```

