def find_solution(a, b, n):
    if a == 0 and b == 0:
        return None if n != 0 else (0, 0)
    if a == 0:
        return None if n % b != 0 else (0, n // b)
    if b == 0:
        return None if n % a != 0 else (n // a, 0)
    if a < 0:
        a, n = -a, -n
    if b < 0:
        b, n = -b, -n
    g, x0, y0 = a, 1, 0
    b0, r, x1, y1 = b, 0, 0, 1
    while b0 != 0:
        q = g // b0
        g, r = b0, g - q * b0
        x0, x1 = x1, x0 - q * x1
        y0, y1 = y1, y0 - q * y1
    if n % g != 0:
        return None
    x0, y0 = x0 * (n // g), y0 * (n // g)
    t = (b // g) * (n // g)
    return (x0 - t, y0 + t)
```

