def count_no_of_ways(n, k):
    if n == 0:
        return 0
    if n == 1:
        return k
    if n == 2:
        return k * k
    same = k * (k - 1)
    diff = k * (k - 1)
    for _ in range(2, n):
        same, diff = diff, (k - 1) * (same + diff)
    return (same + diff) % 1000000007
```

